CREATE TABLE IF NOT EXISTS catalog_parts (id BIGSERIAL PRIMARY KEY, canonical_part_number TEXT NOT NULL UNIQUE, description TEXT, vendor_agnostic BOOLEAN NOT NULL DEFAULT FALSE, vendor_unknown BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS part_aliases (id BIGSERIAL PRIMARY KEY, catalog_part_id BIGINT NOT NULL REFERENCES catalog_parts(id) ON DELETE CASCADE, alias TEXT NOT NULL, UNIQUE(catalog_part_id, alias));
CREATE TABLE IF NOT EXISTS vendor_listings (id BIGSERIAL PRIMARY KEY, catalog_part_id BIGINT NOT NULL REFERENCES catalog_parts(id) ON DELETE CASCADE, vendor_name TEXT NOT NULL, vendor_part_number TEXT NOT NULL, purchase_url TEXT, latest_price NUMERIC(12,2), currency TEXT NOT NULL DEFAULT 'USD', availability TEXT, is_default BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(catalog_part_id, vendor_name, vendor_part_number));
CREATE UNIQUE INDEX IF NOT EXISTS one_default_listing_per_part ON vendor_listings(catalog_part_id) WHERE is_default;
